#pragma once#include "BaseReader.h"class KSCB : public KBaseReader{public:  KSCB();  virtual std::string GetType() const  {    return "SCB";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_Settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_Settings;};//////////////////////////////////////////////////////////////////////////class KSCBFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KSCB();    return ptr;  }};